(window["webpackJsonp"]=window["webpackJsonp"]||[]).push([["chunk-2d0c9199"],{5866:function(n,i,e){"use strict";e.r(i),e.d(i,"Header",(function(){return t})),e.d(i,"Summary",(function(){return l})),e.d(i,"contacts",(function(){return r})),e.d(i,"Achievements",(function(){return a})),e.d(i,"Experience",(function(){return o})),e.d(i,"CoverLetter",(function(){return s})),e.d(i,"Education",(function(){return p})),e.d(i,"Skills",(function(){return d})),e.d(i,"Projects",(function(){return c})),e.d(i,"Certifications",(function(){return u}));const t={name:"Валерий Кацкель",location:"Минск (Беларусь)",position:"HTML5 Game Developer / Playable Ads Developer",sex:"Мужской",yob:"9 октября 1983",degree:"Бакалавр"},l={text:"Frontend-разработчик с 12+ годами опыта и специализацией в создании интерактивного контента и HTML5-игр. Разрабатывал рекламные креативы с использованием PixiJS, WebGL и Canvas API, обеспечивая их высокую производительность и работоспособность на различных устройствах. Имею опыт оптимизации размера ресурсов и кода для быстрой загрузки, анимации игровых элементов и реализации интерактивных механик. Активно применяю TypeScript, работаю с Git и внедряю автоматизированное тестирование для обеспечения качества продукта."},r=[{key:"Эл. почта:",value:"valerykatskel@gmail.com"},{key:"Телефон/WhatsApp/Telegram/Viber",value:"+375297688632"},{key:"Skype:",value:"bestnickname"},{key:"LinkedIn:",value:"https://www.linkedin.com/in/valerykatskel/"},{key:"GitHub:",value:"https://github.com/valerykatskel"}],a=["Разработал серию <strong>интерактивных креативов</strong> для рекламных кампаний с использованием <strong>HTML5, Canvas API и PixiJS</strong>, повысивших конверсию на <strong>25%</strong> по сравнению со статичными форматами","Создал легковесные адаптивные HTML5-игры с размером до <strong>300Kb</strong>, оптимизированные для работы как в десктопных, так и в мобильных браузерах с высокой производительностью","Реализовал систему анимации игровых персонажей с использованием <strong>Spine и PixiJS</strong>, что позволило сократить размер анимационных ассетов на <strong>60%</strong> при сохранении высокого качества","Разработал конвейер оптимизации графических ресурсов для веб-креативов, автоматизировавший процесс сжатия и конвертации изображений и сокративший время подготовки на <strong>70%</strong>","Интегрировал <strong>WebGL-шейдеры</strong> для создания спецэффектов в интерактивных креативах, обеспечив визуальную привлекательность при сохранении высокой производительности","Создал адаптивную систему управления для мобильных игр, автоматически подстраивающуюся под различные устройства и типы взаимодействия (тач, мышь, клавиатура)"],o=[{id:1,name:"Octo Browser",location:"Минск, Беларусь",position:"RnD Инженер",start:"Декабрь 2024",end:"Февраль 2025",type:"Полная занятость",descriptionHeader:"OctoBrowser — продвинутый анти-детект браузер для профессионального маркетинга, обеспечивающий безопасный мультиаккаунтинг.",description:"<p>Ключевые достижения:</p>\n    <ul>\n      <li>Создал алгоритм эмуляции аппаратных спецификаций WebGL и Canvas API, повысивший уникальность цифрового отпечатка браузера на 62%</li>\n      <li>Разработал модуль обнаружения и обхода защиты от автоматизации в веб-приложениях с использованием JavaScript и DOM-манипуляций</li>\n      <li>Оптимизировал рендеринг сложного контента в Canvas, ускорив отрисовку на 35% и снизив нагрузку на CPU</li>\n    </ul>\n    <p>Технологический стек: JavaScript, TypeScript, WebGL, Canvas API, WebRTC, Chrome Extensions API, Puppeteer, Node.js</p>"},{id:2,name:"Social Discovery Ventures",location:"Удаленно",position:"Frontend Team Lead",start:"Май 2022",end:"",type:"Полная занятость",descriptionHeader:"Social Discovery Ventures — коллекция уникальных онлайн-брендов, позволяющих людям по всему миру находить друг друга благодаря силе общих интересов и взаимной выгоды.",description:"<p>Ключевые достижения в области интерактивного контента:</p>\n    <ul>\n      <li>Руководил разработкой серии интерактивных HTML5-демо для знакомства пользователей с функциями сервиса, что повысило конверсию из посетителей в зарегистрированных пользователей на 28%</li>\n      <li>Внедрил технологию WebGL для создания анимированных профилей пользователей, увеличив время взаимодействия с приложением на 42%</li>\n      <li>Оптимизировал производительность видеочата с WebRTC для работы даже на устройствах начального уровня, расширив аудиторию сервиса на 15%</li>\n      <li>Создал систему геймификации пользовательского взаимодействия с использованием PixiJS, повысившую уровень вовлеченности на 35%</li>\n    </ul>\n    <p>Технологический стек: React, TypeScript, PixiJS, WebGL, WebRTC, Jest, Cypress, GitLab CI/CD, Canvas API</p>"},{id:3,name:"TUT.BY",location:"Минск, Беларусь",position:"Frontend Developer",start:"Декабрь 2013",end:"Ноябрь 2020",type:"Полная занятость",descriptionHeader:"TUT.BY — крупнейший новостной и сервисный интернет-портал в Беларуси с ежемесячной аудиторией более 3 миллионов уникальных пользователей.",description:"<p>Разработка интерактивного контента:</p>\n    <ul>\n      <li>Создал более 50 интерактивных игр и тестов с использованием HTML5 Canvas и JavaScript для спецпроектов, которые в среднем генерировали на 140% больше просмотров, чем стандартные материалы</li>\n      <li>Разработал фреймворк для быстрого создания веб-игр и викторин, сократив время производства нового интерактивного контента с недели до 1-2 дней</li>\n      <li>Внедрил технологию динамической адаптации контента под различные устройства, обеспечив единый пользовательский опыт на десктопе и мобильных платформах</li>\n      <li>Оптимизировал производительность анимаций и интерактивных элементов, добившись стабильных 60 FPS даже на устройствах среднего класса</li>\n      <li>Создал серию образовательных игр для детского раздела портала, получивших признание пользователей и образовательных учреждений</li>\n    </ul>\n    <p>Технологический стек: JavaScript, HTML5 Canvas, Vue.js, CreateJS, GreenSock Animation Platform (GSAP), Webpack</p>"},{id:4,name:"Проекты по разработке игр и интерактивного контента",location:"Фриланс",position:"HTML5 Game Developer",start:"2015",end:"2020",type:"Частичная занятость",descriptionHeader:"Разработка HTML5-игр и интерактивных рекламных креативов для различных клиентов",description:"<p>Ключевые проекты:</p>\n    <ul>\n      <li>Разработал серию HTML5-игр для рекламных кампаний брендов FMCG-сектора с интеграцией в социальные сети и мобильные платформы</li>\n      <li>Создал коллекцию playable ads для мобильных игр с конверсией в установку на 45% выше среднерыночной</li>\n      <li>Оптимизировал размеры и производительность игр для соответствия строгим требованиям рекламных сетей (до 300Kb)</li>\n      <li>Внедрил систему аналитики пользовательского поведения в интерактивных креативах для оптимизации конверсии</li>\n      <li>Адаптировал контент для различных рекламных платформ (Facebook Ads, Google UAC, TikTok Ads) с учетом их специфических требований</li>\n    </ul>\n    <p>Технологический стек: PixiJS, Phaser, CreateJS, Canvas API, JavaScript, TypeScript, WebGL, Web Audio API, GSAP</p>"}],s="\n<p>Уважаемая команда маркетинга Awem,</p>\n\n<p>С большим интересом откликаюсь на вакансию Playable Ads Developer / HTML5 Game Developer. Мой многолетний опыт во frontend-разработке с акцентом на создание интерактивного и игрового контента идеально соответствует требованиям этой позиции.</p>\n\n<p>За годы работы я накопил обширные знания и навыки, особенно значимые для разработки playable ads:</p>\n\n<ul>\n  <li>Уверенное владение JavaScript/TypeScript, HTML5 и CSS для создания интерактивных рекламных креативов</li>\n  <li>Опыт работы с игровыми движками, включая PixiJS, Phaser и Canvas API</li>\n  <li>Навыки оптимизации ресурсов и кода для соответствия ограничениям рекламных сетей (легковесность, производительность)</li>\n  <li>Понимание принципов анимации и геймдизайна для создания вовлекающего пользовательского опыта</li>\n  <li>Работа с инструментами контроля версий, сборщиками и системами CI/CD для эффективной разработки</li>\n</ul>\n\n<p>В своих проектах я всегда уделяю особое внимание производительности и оптимизации, понимая, что каждый килобайт и миллисекунда важны для успеха рекламного креатива. Мне нравится решать сложные задачи по балансированию между визуальной привлекательностью и техническими ограничениями.</p>\n\n<p>Я готов применить свой опыт и энтузиазм в создании прорывных playable ads для Awem, привлекающих новых пользователей и повышающих их вовлеченность в ваши игры.</p>\n\n<p>С уважением,<br/>\nВалерий Кацкель</p>\n",p=[{id:1,name:"Полоцкий государственный университет",position:"Бакалавр информационных технологий",start:"2003",end:"2008",description:"Сдал государственный экзамен по специальности с оценкой СЕМЬ и защитил дипломный проект на 9 баллов из 10."}],d=["Разработка игр: <strong>PixiJS, Phaser, CreateJS, Three.js</strong>, Canvas API, WebGL, анимация с GSAP и Spine","Frontend: JavaScript (ES6+), TypeScript, HTML5, CSS3/SCSS/Less, React, Vue.js","Оптимизация: Сжатие графики и звука, профилирование производительности, ShaderToy, текстурные атласы","Инструменты: Webpack, Git, Adobe Photoshop (базовые навыки), Texture Packer, Chrome DevTools","Языки: <strong>Английский (B2)</strong>, сертификат EF SET English <a href='https://www.efset.org/cert/E8BLq3'>https://efset.org/cert/E8BLq3</a>, Русский (родной), Белорусский (родной)","Дополнительные навыки: Базовое понимание игрового дизайна, A/B тестирование, аналитика пользовательского поведения"],c=[{id:"1",name:"Расширяемый интерактивный баннер для мобильных устройств",start:"Дек 2019",end:"Фев 2020",description:"\n      <p>Разработал адаптивный интерактивный баннер с анимированным раскрытием содержимого при взаимодействии пользователя для рекламной кампании.</p>\n      \n      <p><strong>Технические детали:</strong></p>\n      <ul>\n        <li>Разработка на чистом JavaScript без использования фреймворков для максимальной производительности</li>\n        <li>Реализация плавных анимаций с использованием CSS3 transitions и requestAnimationFrame для оптимизации на мобильных устройствах</li>\n        <li>Внедрение жестов (свайп, тап) с корректной обработкой на различных устройствах</li>\n        <li>Оптимизация загрузки изображений (прогрессивная загрузка, WebP формат) для ускорения инициализации</li>\n        <li>Автоматические тесты с использованием Cypress для кроссбраузерной совместимости</li>\n      </ul>\n      \n      <p><strong>Результаты:</strong></p>\n      <ul>\n        <li>Увеличение конверсии на 18% по сравнению со статическими баннерами</li>\n        <li>Сокращение времени загрузки на 40% за счет оптимизаций</li>\n        <li>Поддержка более 95% мобильных устройств на рынке</li>\n      </ul>\n    ",url:"https://valerykatskel.github.io/expandable-banner/"},{id:"2",name:"HTML5 игра для рекламной кампании",start:"Мар 2018",end:"Апр 2018",description:"\n      <p>Создал казуальную HTML5-игру для использования в качестве playable ad мобильной игры-головоломки.</p>\n      \n      <p><strong>Технические детали:</strong></p>\n      <ul>\n        <li>Разработка с использованием PixiJS для рендеринга и управления игровым процессом</li>\n        <li>Создание системы частиц для визуальных эффектов с оптимизацией для мобильных устройств</li>\n        <li>Внедрение прогрессивной сложности для демонстрации разных аспектов рекламируемой игры</li>\n        <li>Оптимизация игровых ресурсов и логики для размера менее 250Kb</li>\n        <li>Интеграция с различными рекламными сетями (Facebook Ads, Google UAC)</li>\n      </ul>\n      \n      <p><strong>Результаты:</strong></p>\n      <ul>\n        <li>CTR на 32% выше, чем у стандартных видеообъявлений</li>\n        <li>Конверсия в установку выше на 28% по сравнению с другими форматами</li>\n        <li>Среднее время взаимодействия с креативом - 45 секунд</li>\n      </ul>\n    "},{id:"3",name:"Интерактивный онлайн-квиз с геймификацией",start:"Сен 2019",end:"Окт 2019",description:"\n      <p>Разработал образовательную игру-квиз с элементами геймификации для медиа-проекта.</p>\n      \n      <p><strong>Технические детали:</strong></p>\n      <ul>\n        <li>Использование Vue.js для управления состоянием приложения и компонентной структуры</li>\n        <li>Интеграция Canvas API для анимированных визуальных элементов и переходов</li>\n        <li>Создание адаптивного интерфейса для корректного отображения на разных устройствах</li>\n        <li>Внедрение системы сбора аналитики пользовательских действий</li>\n        <li>Оптимизация для быстрой загрузки контента и плавной работы даже на слабых устройствах</li>\n      </ul>\n      \n      <p><strong>Результаты:</strong></p>\n      <ul>\n        <li>Более 50,000 уникальных прохождений за первый месяц</li>\n        <li>Среднее время, проведенное пользователем в приложении - 4.5 минуты</li>\n        <li>Показатель возвращаемости - 18%</li>\n      </ul>\n    "}],u=[{id:1,img:"https://media-exp1.licdn.com/dms/image/C4D0BAQE0iRUqSJueUw/company-logo_100_100/0?e=1601510400&v=beta&t=ywN-hQPlpWAdbDClxRcOIRLthOyFMOEh92Sns0OtSR8",name:"EF Standard English Test (EF SET)",company:"EF Standard English Test (EF SET)",issued:"Янв 2020",description:"efset.org/cert/E8BLq3 | B2 Выше среднего | 56/100"},{id:2,img:"https://media-exp1.licdn.com/dms/image/C4D0BAQGyOWvr4W0Pow/company-logo_100_100/0?e=1601510400&v=beta&t=q6BmTUrPzrNdHaXnFWIYLZRz7tC3ji_UxUXZNTks_u8",name:"JavaScript и JSON: Техники интеграции",company:"LinkedIn",issued:"Янв 2020",description:"Идентификатор AdpyyJxmdIhTequ-hJcsdbMM1EPT"}]}}]);
